/*
 * A192598  Monotonic ordering of set S generated by these rules: if x and y
 *          are in S and x^2+2y^2 is a prime, then x^2+2y^2 is in S, and 1 is
 *          in S.
 * https://oeis.org/A192598
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, fini, full
 * Formula:   not stated
 * Range:     u8 n <= 4, u16 n <= 4, u32 n <= 7, u64 n <= 7, u128 n <= 7,
 *            big any n
 * Helpers:   is_prime_big
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* A192598: Monotonic ordering of the closure of S.
   S starts with {1}.  If x,y∈S and p=x²+2y² is prime, then p∈S.
   a(n) is the n‑th smallest element of S (a(1)=1,a(2)=3,…) */

/* Note: the implementation assumes little‑endian byte order for the
   prime test is_prime_big, which works for uint64_t and arbitrary
   precision types provided by the build environment.  It lazily
   generates and caches the entire closed set. */

#include <stdlib.h>
#include <stdbool.h>
#include <stdint.h>
#include "../utils/is_prime_big.h"   /* bool is_prime_big(seq_t n) */

/* Comparator for qsort that works with any seq_t that supports <. */
static int cmp_seq(const void *a, const void *b)
{
    const seq_t va = *(const seq_t *)a;
    const seq_t vb = *(const seq_t *)b;
    if (va < vb) return -1;
    return va > vb ? 1 : 0;
}

/* Dynamic array of all elements generated so far. */
static seq_t *S      = NULL;   /* array of elements */
static size_t S_cap  = 0;      /* capacity allocated */
static size_t S_len  = 0;      /* number of elements currently stored */
static bool   built  = false;  /* have we finished building S? */

/* Append a new element to S, reallocating if necessary. */
static void append_seq(seq_t v)
{
    if (S_len >= S_cap) {
        size_t new_cap = S_cap ? S_cap << 1 : 16;
        seq_t *tmp = (seq_t *)realloc(S, new_cap * sizeof(seq_t));
        if (!tmp) abort();          /* Out‑of‑memory */
        S = tmp;
        S_cap = new_cap;
    }
    S[S_len++] = v;
}

/* Generate the closure of S until no new elements appear. */
static void build_seq(void)
{
    if (built) return;

    /* Start set {1} */
    append_seq((seq_t)1);

    bool changed = true;
    while (changed) {
        changed = false;
        size_t current = S_len;            /* elements to pair this round */

        for (size_t i = 0; i < current; ++i) {
            seq_t xi = S[i];
            seq_t xi2 = xi * xi;           /* x² */

            for (size_t j = 0; j < current; ++j) {
                seq_t yj = S[j];
                seq_t p = xi2 + (seq_t)2 * (yj * yj);  /* x²+2y² */

                if (p < (seq_t)2) continue;        /* 0,1 not prime */

                if (!is_prime_big(p)) continue;    /* composite */

                /* Check if p already present */
                bool present = false;
                for (size_t k = 0; k < S_len; ++k) {
                    if (S[k] == p) { present = true; break; }
                }
                if (present) continue;

                append_seq(p);
                changed = true;
            }
        }
    }

    /* Sort the array for fast index lookup */
    qsort(S, S_len, sizeof(seq_t), cmp_seq);
    built = true;
}

/* Return the nth term (1‑based).  Returns 0 if n < 1 or beyond the
   generated set (the sequence is finite). */
seq_t a(idx_t n)
{
    if (n == 0) return (seq_t)0;  /* undefined, return 0 for safety */

    build_seq();

    if ((size_t)n <= S_len) return S[(size_t)n - 1];
    return (seq_t)0;              /* beyond computed terms */
}
